#include <iostream>
#include <stdexcept>
using namespace auriga::item;namespace f=effect_runtime_fixture;namespace pf=persistent_item_fixture;namespace cf=item_catalog_fixture;
namespace {
unsigned checks=0;void Check(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}
ItemKey Crystal(){return ItemKey::Create(ItemCategory::Consumable,90001).value();}
ItemCatalogSource Source(){
 auto s=f::Catalog();auto base=*std::ranges::find(s.items,cf::TimedPotion(),&ItemBaseRow::key);base.key=Crystal();base.contentCode="energy.fixture";base.minimumLevel=35;base.maxStack=200;s.items.push_back(base);
 s.timedEffectGroups.push_back({90001,"energy.fixture",TimedEffectReapply::Reject,TimedEffectClock::OnlineTime,false});
 s.timedEffects.push_back({90001,"energy.fixture",90001,0,1800000,1,15,true,{},TimedEffectUtility::Energy});s.consumables.push_back({Crystal(),0,90001});
 for(auto [percent,chance]:{std::pair{1,500},std::pair{3,1000},std::pair{5,4500},std::pair{7,2500},std::pair{10,1500}})s.energyCrystalTiers.push_back({90001,static_cast<std::uint8_t>(percent),static_cast<std::uint16_t>(chance)});
 s.attributeBindings.push_back({cf::Armor(),1});return s;
}
void Birth(){auto c=BuildItemCatalog(Source()).value();std::map<unsigned,unsigned> histogram;
 for(unsigned roll=1;roll<=10000;++roll){const auto value=RollEnergyCrystal(*c,Crystal(),roll);Check(value.has_value(),"all authored birth probabilities assigned exactly once");++histogram[value->percent];}
 Check(histogram==std::map<unsigned,unsigned>{{1,500},{3,1000},{5,4500},{7,2500},{10,1500}},"original energy distribution exact at every boundary");Check(!RollEnergyCrystal(*c,Crystal(),0) && !RollEnergyCrystal(*c,Crystal(),10001),"invalid RNG decisions refused");
 auto invalid=Source();invalid.energyCrystalTiers.back().chanceBp--;Check(!BuildItemCatalog(invalid),"probability gaps refused");invalid=Source();invalid.energyCrystalTiers.push_back(invalid.energyCrystalTiers.back());Check(!BuildItemCatalog(invalid),"duplicate birth outcomes refused");
 const ItemOwnerFence fence{pf::Character(),1,1};const std::array layouts{pf::Inventory()};const std::array ids{ItemInstanceId::Create(100).value(),ItemInstanceId::Create(101).value()};
 const auto grant=MakeGrantCommit(*c,{55},fence,layouts,{},ItemGrant{Crystal(),0,201},ids);Check(grant.has_value() && grant->items.size()==2,"actual native issuer creates separate source-sized stacks");
 for(const auto& ch:grant->items){Check(ch.after.energy==InitialEnergyCrystal(*c,Crystal(),grant->operationId,ch.after.id.Value()),"birth fixed to actual server-issued instance and operation");auto bad=*grant;bad.items[0].after.energy->percent=bad.items[0].after.energy->percent==1 ? 10 : 1;Check(!ValidateItemCommit(*c,bad),"forged creation strength refused");}
 auto born=grant->items[0].after;born.placement->anchor=0;const std::array inventory{born};const auto move=MakeMoveCommit(*c,{55,1},fence,layouts,inventory,born.id,{ItemStorageKind::Inventory,1,8});Check(move && move->items[0].after.energy==born.energy,"moving never rerolls energy");auto tampered=*move;tampered.items[0].after.energy->percent=born.energy->percent==1 ? 10 : 1;Check(!ValidateItemCommit(*c,tampered),"movement cannot change the stored roll");
 auto packet=EncodeTypedInventory(*c,layouts,{},inventory).value();const auto decoded=DecodeTypedInventory(packet,fence.owner);Check(packet[5]==std::byte{29} && decoded && decoded->items[0].energy==born.energy && decoded->energyDurations.at(born.id)==1800000,"actual GC225v29 carries strength and original duration");packet[5]=std::byte{28};Check(!DecodeTypedInventory(packet,fence.owner),"old clients cannot silently lose energy state");
 const std::array dropLayouts{layouts[0],ItemStorageLayout{{fence.owner,ItemStorageKind::TradeEscrow,1},5,9,4}};const auto split=MakeGroundDropCommit(*c,{55,9},fence,dropLayouts,inventory,born.id,{ItemStorageKind::TradeEscrow,1,0},1,ItemInstanceId::Create(500).value());
 Check(split && split->items[1].after.energy==born.energy && split->items[0].after.count==199,"ground stack split retains exact original strength without rerolling");auto forged=*split;forged.items[1].after.energy->percent=born.energy->percent==1 ? 10 : 1;Check(!ValidateItemCommit(*c,forged),"split cannot substitute another authored strength");forged=*split;++forged.items[0].after.count;Check(!ValidateItemCommit(*c,forged),"split cannot create free energy units");
}
void Effects(){auto c=BuildItemCatalog(Source()).value();const ItemOwnerFence fence{pf::Character(),1,1};const std::array layouts{pf::Inventory()};const std::array ids{ItemInstanceId::Create(100).value()};auto crystal=MakeGrantCommit(*c,{55},fence,layouts,{},ItemGrant{Crystal(),0,2},ids)->items[0].after;
 const std::array items{crystal};auto facts=f::Facts();RecoverySchedule empty;const auto use=MakeItemEffectUse(*c,{55,2},fence,layouts,items,empty,crystal.id,facts,0,100000,42);Check(use && use->items[0].after.count==1 && use->recovery->after.effects[0].energyPercent==crystal.energy->percent,"one crystal and exact timed strength commit together");auto state=use->recovery->after;
 Check(!MakeItemEffectUse(*c,{55,3},fence,layouts,items,state,crystal.id,facts,0,100000,43),"second crystal refused while energy active");facts.existingUtilityMask=4;Check(!MakeItemEffectUse(*c,{55,4},fence,layouts,items,empty,crystal.id,facts,0,100000,43),"authoritative original legacy blend conflict refused");facts.existingUtilityMask=0;facts.actor.level=34;Check(!MakeItemEffectUse(*c,{55,5},fence,layouts,items,empty,crystal.id,facts,0,100000,43),"original level35 gate preserved");facts=f::Facts();facts.alive=false;auto death=state;NormalizeTimedItems(*c,death,999999999,&facts);Check(death==state,"original energy survives death and offline wall time");
 auto advanced=AdvanceRecoverySchedule(*c,state,12345).value();Check(advanced.effects[0].remainingMs==1787655 && advanced.effects[0].energyPercent==crystal.energy->percent,"measured online elapsed preserves fixed strength");const auto blob=EncodeRecoverySchedule(*c,advanced).value();Check(blob[3]=='5' && DecodeRecoverySchedule(*c,blob)==advanced,"RCS5 persists exact strength and remaining online time");for(unsigned n=0;n<blob.size();++n)Check(!DecodeRecoverySchedule(*c,std::span(blob).first(n)),"every truncated energy recovery record refused");auto corrupt=advanced;corrupt.effects[0].energyPercent=2;Check(!ValidateRecoverySchedule(*c,corrupt),"unauthored stored strength refused");Check(AdvanceRecoverySchedule(*c,advanced,1800000)->effects.empty(),"expired energy fully clears");
 const auto frame=EncodeItemEffectsRuntime(*c,{1,255,10,11,&crystal,&state,items,100000});Check(frame && (*frame)[5]==std::byte{5},"actual energy preview and active list use GC243v5");
}
void Attributes(){auto c=BuildItemCatalog(Source()).value();std::vector<PersistentItem> gear;
 for(unsigned n=0;n<2;++n){PersistentItem p{ItemInstanceId::Create(300+n).value(),n ? cf::Armor() : cf::Sword(),pf::Character()};p.placement=ItemPlacement{ItemStorageKind::Equipment,1,n};p.attributes.slots[0]=BonusEntry{BonusId::PhysicalAttackFlat,19000};p.attributes.slots[1]=BonusEntry{BonusId::PhysicalDefenseFlat,9000};p.attributes.lockedSlot=1;p.attributes.slots[5]=BonusEntry{BonusId::CritChance,n ? 900 : 100};gear.push_back(p);}
 auto bonus=EnergyEquipmentBonuses(*c,gear,10).value();Check(bonus==std::vector<BonusEntry>{{BonusId::PhysicalAttackFlat,3000},{BonusId::CritChance,100}},"aggregate original attributes first, exclude lock, truncate in each original APPLY unit");
 const auto plain=BuildEquipmentStats(*c,pf::Character(),gear).value(),energized=BuildEquipmentStats(*c,pf::Character(),gear,bonus).value();Check(energized.flat.physicalAttackRaw==plain.flat.physicalAttackRaw+3000 && energized.flat.physicalDefenseRaw==plain.flat.physicalDefenseRaw && energized.Bonus(BonusId::CritChance)==plain.Bonus(BonusId::CritChance)+100,"energy reaches the real equipment formula once without scaling base stats or locked attributes");
 auto bag=gear[0];bag.id=ItemInstanceId::Create(400).value();bag.placement=ItemPlacement{ItemStorageKind::Inventory,1,0};gear.push_back(bag);Check(EnergyEquipmentBonuses(*c,gear,10)==bonus,"unequipped attributes never contribute");gear[0].placement->anchor=20;Check(EnergyEquipmentBonuses(*c,gear,10).value()==std::vector<BonusEntry>{{BonusId::PhysicalAttackFlat,1000}},"only original eight slots contribute, percentage aggregate rounding preserved");
}
}
int main(){try{Birth();Effects();Attributes();std::cout<<checks<<" Energy crystal checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
